import{_ as a,o as i,c as e,a3 as h}from"./chunks/framework.Ba39LDvt.js";const u=JSON.parse('{"title":"关于本站","description":"上海科技大学 IC 荣誉项目学生发起、贡献者共同维护的非官方集成电路知识社区。","frontmatter":{"title":"关于本站","description":"上海科技大学 IC 荣誉项目学生发起、贡献者共同维护的非官方集成电路知识社区。"},"headers":[],"relativePath":"about/index.md","filePath":"about/index.md","lastUpdated":1795525699000}'),r={name:"about/index.md"};function d(n,t,o,c,s,b){return i(),e("div",null,[...t[0]||(t[0]=[h('<h1 id="关于本站" tabindex="-1">关于本站 <a class="header-anchor" href="#关于本站" aria-label="Permalink to &quot;关于本站&quot;">​</a></h1><p>上科大芯知库（ShanghaiTech IC Wiki）由上海科技大学 IC 荣誉项目学生独立发起，内容由贡献者共同维护，面向初学者、在校生、校友及其他集成电路爱好者。我们希望把课程、科研方向、教授与课题组、平台、培养项目和成长经验连成一张可用的地图，让刚入门的同学知道从哪里开始，也让已有方向的同学更容易查漏补缺。文章代表各自作者的观点。</p><h2 id="缘起-把公开信息与学生经验连起来" tabindex="-1">缘起：把公开信息与学生经验连起来 <a class="header-anchor" href="#缘起-把公开信息与学生经验连起来" aria-label="Permalink to &quot;缘起：把公开信息与学生经验连起来&quot;">​</a></h2><p>我们参考并致敬 <a href="https://njuic-students.github.io/" target="_blank" rel="noreferrer">NJU「集成全家桶」</a>、<a href="https://crys-chen.github.io/ic-guide/" target="_blank" rel="noreferrer">IC 自学指南</a>与 <a href="https://csdiy.wiki/" target="_blank" rel="noreferrer">CS 自学指南</a>。这些项目展示了一种值得学习的方式：把零散资源组织成路径，把个人走过的弯路整理成可以持续修正的公共知识。</p><p>本站不想再写一遍互联网上已有的全部 IC 教材。对于通用知识，我们尽量给出简洁解释、先修关系和可靠入口；更希望把时间用在<strong>上科大独有信息</strong>上：哪些课程能够接起来、哪些老师公开从事什么方向、有哪些可利用的平台和培养项目，以及不同年份的真实学习经验。</p><p>参考不等于复制。外校的培养方案、选课规则和经验不能直接移植到上科大；他站的文字、图片与资料也各有版权。我们以自己的组织和说明连接资源，引用时注明出处，不因“网上能找到”就重新分发。</p><h2 id="内容怎样组织" tabindex="-1">内容怎样组织 <a class="header-anchor" href="#内容怎样组织" aria-label="Permalink to &quot;内容怎样组织&quot;">​</a></h2><table tabindex="0"><thead><tr><th>板块</th><th>一句话说明</th></tr></thead><tbody><tr><td><a href="/shanghaitech-ic-wiki-dev.github.io/basics/">科普基础</a></td><td>理解集成电路、产业链、设计流程、器件与常用术语。</td></tr><tr><td><a href="/shanghaitech-ic-wiki-dev.github.io/map/">学习地图</a></td><td>按数字、模拟、器件与 EDA 方向把基础和进阶知识接起来。</td></tr><tr><td><a href="/shanghaitech-ic-wiki-dev.github.io/courses/">上科大课程</a></td><td>以官方开课资料为基础，配合注明版本的中性学习建议。</td></tr><tr><td><a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/">上科大特色</a></td><td>整理教授、实验室、平台与培养项目的公开信息。</td></tr><tr><td><a href="/shanghaitech-ic-wiki-dev.github.io/research/">科研方向</a></td><td>从问题、方法和本校研究力量认识 IC 的不同分支。</td></tr><tr><td><a href="/shanghaitech-ic-wiki-dev.github.io/self-learning/">自学路线</a></td><td>用公开教材、课程与项目补齐知识链。</td></tr><tr><td><a href="/shanghaitech-ic-wiki-dev.github.io/eda/">EDA 工具</a></td><td>了解商业与开源工具，以及环境、授权和工作流。</td></tr><tr><td><a href="/shanghaitech-ic-wiki-dev.github.io/research-guide/">科研探索</a></td><td>学习进组、读论文、管理工具、写作和汇报的方法。</td></tr><tr><td><a href="/shanghaitech-ic-wiki-dev.github.io/competitions/">竞赛实践</a></td><td>按目标选择竞赛与长期工程训练。</td></tr><tr><td><a href="/shanghaitech-ic-wiki-dev.github.io/career/">升学就业</a></td><td>比较推免、境外申请、考研、实习与岗位选择。</td></tr><tr><td><a href="/shanghaitech-ic-wiki-dev.github.io/links/">友链</a></td><td>保留值得长期访问的官方与社区资源入口。</td></tr></tbody></table><p>不需要顺序读完全部页面。第一次接触 IC，可以从基础与地图开始；已经明确方向，可以直接看课程、科研和自学路线。页面之间的链接是建议路径，不是必须完成的任务清单。</p><h2 id="事实、建议与经验分开写" tabindex="-1">事实、建议与经验分开写 <a class="header-anchor" href="#事实、建议与经验分开写" aria-label="Permalink to &quot;事实、建议与经验分开写&quot;">​</a></h2><p>课程、招生、导师、平台等事实以官方资料为依据，年份与适用范围尽量写清楚；学习路线是编辑建议；往届经验是特定时间、特定条件下的记录。三者不能互相替代。我们不编造教师经历，不评价个人性格，也不提供“保证录取”“一定进组”等承诺。</p><p>发现不确定内容，宁可缩小结论或请读者查官网，也不补上一个看似完整的答案。页面过时不可避免，重要决策请回到最新官方文件。你可以通过<a href="/shanghaitech-ic-wiki-dev.github.io/about/contribute">参与共建</a>提出有来源的纠错，不需要等到写完一整篇文章。</p><h2 id="非官方声明" tabindex="-1">非官方声明 <a class="header-anchor" href="#非官方声明" aria-label="Permalink to &quot;非官方声明&quot;">​</a></h2><p>本站不是上海科技大学、信息科学与技术学院或任何实验室的官方站点，不代表学校、教师或企业立场，也不提供招生、选课、资源使用或就业结果保证。学校名称、机构名称与相关标识的权益归各自权利人所有。外链由第三方维护，本站无法保证其持续有效或内容不变。</p><p>本站不公开学生个人姓名、成绩、账号、私人联系方式、内网信息或保密科研材料；教授信息仅限公开学术资料。对于隐私或权利问题，请通过仓库联系维护者，说明需处理的页面与位置，不要在公开 Issue 中再次贴出敏感原文。</p><h2 id="许可证" tabindex="-1">许可证 <a class="header-anchor" href="#许可证" aria-label="Permalink to &quot;许可证&quot;">​</a></h2><p>网站代码、配置、工作流与脚本采用 <a href="https://github.com/ShanghaiTech-IC-Wiki-Dev/shanghaitech-ic-wiki-dev.github.io/blob/main/LICENSE" target="_blank" rel="noreferrer">MIT License</a>。原创文章、Markdown 模板、项目说明及标明为原创的配图采用 <a href="https://github.com/ShanghaiTech-IC-Wiki-Dev/shanghaitech-ic-wiki-dev.github.io/blob/main/LICENSE-CONTENT" target="_blank" rel="noreferrer">CC BY 4.0</a>。</p><p>再使用原创内容时，请注明作者、出处、许可与所作修改。第三方素材、依赖及外部资源遵循各自的许可，具体标注优先：课程课件、论文图片、工具、代码、商标及外链资源不因被本站提及而自动适用上述许可，使用前需分别核对。引用官方信息也不意味着官方为本站背书。</p><h2 id="社区与共建" tabindex="-1">社区与共建 <a class="header-anchor" href="#社区与共建" aria-label="Permalink to &quot;社区与共建&quot;">​</a></h2><p>欢迎上科大学生、校友和愿意提供可靠公开资料的朋友参与。一个错字修正、一个失效链接、一段带年份的课程经验，都比等待“完美版本”更有帮助。我们希望这是一份不断积累、能够被下一届继续接手的公共笔记，而不是只属于某个人的资料夹。协作时请遵守<a href="https://github.com/ShanghaiTech-IC-Wiki-Dev/shanghaitech-ic-wiki-dev.github.io/blob/main/CODE_OF_CONDUCT.md" target="_blank" rel="noreferrer">社区行为准则</a>。</p><table tabindex="0"><thead><tr><th>我想做什么</th><th>从这里开始</th></tr></thead><tbody><tr><td>交流学习问题、讨论选题、寻找合作者</td><td><a href="https://github.com/ShanghaiTech-IC-Wiki-Dev/shanghaitech-ic-wiki-dev.github.io/discussions" target="_blank" rel="noreferrer">GitHub Discussions（社区讨论）</a></td></tr><tr><td>报告问题、推荐资源、提交文章</td><td><a href="/shanghaitech-ic-wiki-dev.github.io/about/contribute">参与共建</a></td></tr><tr><td>查看 Markdown、公式、代码与图表的写法</td><td><a href="/shanghaitech-ic-wiki-dev.github.io/about/writing">文章写作示例</a></td></tr><tr><td>查阅贡献记录、为引用的材料署名</td><td><a href="/shanghaitech-ic-wiki-dev.github.io/about/contributors">贡献者与署名</a></td></tr><tr><td>接手站点构建、发布或迁移</td><td><a href="/shanghaitech-ic-wiki-dev.github.io/about/maintenance">站点维护</a></td></tr></tbody></table><p>还没有准备好写文章？在<a href="https://github.com/ShanghaiTech-IC-Wiki-Dev/shanghaitech-ic-wiki-dev.github.io/issues" target="_blank" rel="noreferrer">议题列表</a>里补充一个失效链接的替代来源，也能帮助读者。</p>',22)])])}const l=a(r,[["render",d]]);export{u as __pageData,l as default};
